insert into public.learning_cards (lesson_id, position, title, blocks) values ('8adc4d1a-69f6-5a2c-b851-0c7c8f20d890', 1, '35 dollars pour une légende', '[{"type":"keyfigure","value":"35 $","label":"Le prix payé en 1971 pour dessiner le Swoosh"},{"type":"text","text":"Carolyn Davidson, étudiante en graphisme à Portland, dessine le Swoosh pour la marque qui va devenir Nike, du nom de la déesse grecque de la victoire."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('8adc4d1a-69f6-5a2c-b851-0c7c8f20d890', 2, 'Just Do It', '[{"type":"text","text":"En 1988, l’agence Wieden+Kennedy lance le slogan Just Do It. Trois mots qui deviennent l’un des slogans les plus célèbres de l’histoire de la pub."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('8adc4d1a-69f6-5a2c-b851-0c7c8f20d890', 3, 'Un crocodile et deux C', '[{"type":"text","text":"René Lacoste, champion de tennis surnommé « le crocodile », brode l’animal sur ses polos dès 1933. Chez Chanel, deux C entrelacés signent la maison depuis les années 1920."}]'::jsonb);
