insert into public.learning_cards (lesson_id, position, title, blocks) values ('8177f5e9-2d52-5793-aecc-f056dcd97c5f', 1, 'La pomme croquée', '[{"type":"text","text":"Le tout premier logo d’Apple, en 1976, montre Isaac Newton sous un arbre. En 1977, Rob Janoff dessine la pomme croquée, rayée d’arc-en-ciel jusqu’en 1998."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('8177f5e9-2d52-5793-aecc-f056dcd97c5f', 2, 'Une signature de 1886', '[{"type":"text","text":"Le logo de Coca-Cola est écrit à la main en 1886 par Frank Mason Robinson, le comptable du créateur de la boisson. Il a très peu changé depuis."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('8177f5e9-2d52-5793-aecc-f056dcd97c5f', 3, 'Des mascottes centenaires', '[{"type":"list","items":["1898 : Bibendum, le bonhomme en pneus de Michelin, par O’Galop.","1971 : Starbucks ouvre à Seattle avec une sirène à deux queues pour emblème."]}]'::jsonb);
insert into public.lesson_items (lesson_id, position, question_id) values ('8177f5e9-2d52-5793-aecc-f056dcd97c5f', 1, '9634b785-60bc-524e-b6d8-c9ed3e319c11');
