insert into public.learning_cards (lesson_id, position, title, blocks) values ('29c18d85-8404-5521-aa02-65dab02db2d2', 1, 'La flèche de FedEx', '[{"type":"text","text":"Regarde l’espace blanc entre le E et le x de FedEx : il forme une flèche. Le logo, dessiné par Lindon Leader en 1994, suggère la vitesse et la direction."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('29c18d85-8404-5521-aa02-65dab02db2d2', 2, 'De A à Z', '[{"type":"text","text":"La flèche orange d’Amazon part du a et pointe vers le z : on trouve tout sur Amazon. Elle forme aussi un sourire."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('29c18d85-8404-5521-aa02-65dab02db2d2', 3, 'Un ours dans la montagne', '[{"type":"text","text":"Le Cervin du logo Toblerone cache un ours debout, symbole de Berne, la ville où est né le chocolat. Et en 1977, Milton Glaser dessine I ♥ NY sur un coin de table, gratuitement."}]'::jsonb);
