insert into public.learning_cards (lesson_id, position, title, blocks) values ('2a5202ec-b86f-5a4f-9b7b-2519a8a02eb0', 1, 'Avec ou sans pieds', '[{"type":"text","text":"Les empattements, ou serifs, sont les petites extensions au bout des lettres, comme dans Times New Roman. Une police sans serif, comme Helvetica, en est dépourvue."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('2a5202ec-b86f-5a4f-9b7b-2519a8a02eb0', 2, 'Helvetica, la star suisse', '[{"type":"keyfigure","value":"1957","label":"Création d’Helvetica en Suisse"},{"type":"text","text":"Max Miedinger et Eduard Hoffmann la dessinent sous le nom de Neue Haas Grotesk. Elle prend ensuite le nom latin de la Suisse."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('2a5202ec-b86f-5a4f-9b7b-2519a8a02eb0', 3, 'Un panthéon de polices', '[{"type":"list","items":["Garamond : d’après Claude Garamond, graveur parisien du XVIe siècle.","Futura : Paul Renner, 1927.","Times New Roman : créée en 1932 pour le journal The Times.","Comic Sans : Vincent Connare, 1994, chez Microsoft."]}]'::jsonb);
