insert into public.learning_cards (lesson_id, position, title, blocks) values ('87b1f812-f9f2-5b91-8be5-985b694200fe', 1, 'Le Bauhaus', '[{"type":"text","text":"Fondée en 1919 à Weimar par l’architecte Walter Gropius, l’école du Bauhaus mélange art, artisanat et industrie. Elle déménage à Dessau en 1925 et ferme en 1933 sous la pression des nazis."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('87b1f812-f9f2-5b91-8be5-985b694200fe', 2, 'La forme suit la fonction', '[{"type":"fact","text":"La formule vient de l’architecte américain Louis Sullivan. Elle résume le modernisme : un objet doit d’abord être utile, sa beauté vient de là."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('87b1f812-f9f2-5b91-8be5-985b694200fe', 3, 'Des signatures', '[{"type":"list","items":["Paul Rand : le logo rayé d’IBM (1972).","Saul Bass : les génériques de Vertigo et Psychose.","Andy Warhol : les boîtes de soupe Campbell’s (1962), icône du pop art."]}]'::jsonb);
insert into public.lesson_items (lesson_id, position, question_id) values ('87b1f812-f9f2-5b91-8be5-985b694200fe', 1, '7f98a352-2bd9-5d34-b5d0-dd6315a2bf93');
