insert into public.learning_cards (lesson_id, position, title, blocks) values ('7ce55e7b-6936-5bee-9625-2cec380009e2', 1, 'Écran ou papier', '[{"type":"text","text":"Un écran mélange de la lumière : rouge, vert, bleu (RVB). Une imprimante mélange des encres : cyan, magenta, jaune et noir (CMJN). Un fichier pour l’impression se prépare donc en CMJN."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('7ce55e7b-6936-5bee-9625-2cec380009e2', 2, 'Un numéro par couleur', '[{"type":"keyfigure","value":"1963","label":"Lancement du nuancier Pantone"},{"type":"text","text":"Pantone donne un numéro à chaque couleur pour qu’elle soit identique partout dans le monde. Depuis 2000, la marque élit une couleur de l’année."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('7ce55e7b-6936-5bee-9625-2cec380009e2', 3, 'Les opposés s’attirent', '[{"type":"text","text":"Sur le cercle chromatique, deux couleurs face à face sont complémentaires : bleu et orange, rouge et vert, violet et jaune. Côte à côte, elles se font ressortir."}]'::jsonb);
insert into public.lesson_items (lesson_id, position, question_id) values ('7ce55e7b-6936-5bee-9625-2cec380009e2', 1, 'b5316c82-3f9d-566c-a0ef-a0231eb804de');
